syntax:
```c++
template <typename T>
constexpr T square(T x) { return x * x; }

int main() {
  constexpr int i = square<int>(5); // Compile-time calculation
  constexpr double d = square<double>(5.5); // Compile-time calculation
  std::cout << i << " " << d << std::endl;
  return 0;
}
